def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    clues = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 8)]
    if not eight or not clues:
        return out

    r0 = min(r for r, c in eight)
    r1 = max(r for r, c in eight)
    c0 = min(c for r, c in eight)
    c1 = max(c for r, c in eight)

    cr0 = min(r for r, c in clues)
    cr1 = max(r for r, c in clues)
    cc0 = min(c for r, c in clues)
    cc1 = max(c for r, c in clues)

    clue = [[0] * (cc1 - cc0 + 1) for _ in range(cr1 - cr0 + 1)]
    for r, c in clues:
        clue[r - cr0][c - cc0] = grid[r][c]

    # Rotate the colored pattern clockwise.
    clue = [list(row) for row in zip(*clue[::-1])]
    ch, cw = len(clue), len(clue[0])

    scale = max(1, (r1 - r0 + 1) // ch)
    colors = {}
    for i in range(ch):
        for j in range(cw):
            if clue[i][j]:
                colors[(i, j)] = clue[i][j]

    counts = {}
    for color in colors.values():
        counts[color] = counts.get(color, 0) + 1

    def nearest_color(i, j):
        return min(
            colors.items(),
            key=lambda item: (
                abs(item[0][0] - i) + abs(item[0][1] - j),
                counts[item[1]]
            )
        )[1]

    for r, c in eight:
        i = min(ch - 1, (r - r0) // scale)
        j = min(cw - 1, (c - c0) // scale)
        color = clue[i][j] or nearest_color(i, j)
        out[r][c] = color

    return out
